import{_ as a,o,c as n,a2 as i}from"./chunks/framework.DZhUhjDB.js";const p=JSON.parse('{"title":"Módulo 01 — Fundamentos Blue Team y SOC","description":"","frontmatter":{"title":"Módulo 01 — Fundamentos Blue Team y SOC"},"headers":[],"relativePath":"modules/blue-team/01-fundamentos-blue-team-y-soc.md","filePath":"modules/blue-team/01-fundamentos-blue-team-y-soc.md","lastUpdated":1787330151000}'),l={name:"modules/blue-team/01-fundamentos-blue-team-y-soc.md"};function s(t,e,r,d,u,c){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="modulo-01-—-fundamentos-blue-team-y-soc" tabindex="-1">Módulo 01 — Fundamentos Blue Team y SOC</h1><blockquote><p><strong>Área:</strong> 03-blue-team-defensa<br><strong>Rol principal al que aporta:</strong> SOC Analyst (Nivel 1–2), base para Incident Responder y Threat Hunter.</p></blockquote><hr><h2 id="_1-mision-del-modulo" tabindex="-1">1. Misión del módulo</h2><p>Este módulo introduce al estudiante en el mundo del <strong>Blue Team</strong> desde el punto de vista más operativo: el <strong>Centro de Operaciones de Seguridad (SOC)</strong>.</p><p>La misión es que el estudiante entienda qué hace realmente un SOC en la vida real, qué tipo de datos ve a diario (logs, alertas, eventos) y cómo se encaja eso dentro de la defensa de una organización.</p><p>Al terminar el módulo, el estudiante debe tener un mapa mental claro de:</p><ul><li>Qué es un Blue Team, qué es un SOC y en qué se diferencia de Red/Purple Team.</li><li>Qué tipo de telemetría y herramientas se usan para <strong>monitorizar y detectar</strong> actividad sospechosa.</li><li>Cómo se ve, a alto nivel, el <strong>flujo de trabajo de un analista de SOC</strong>.</li></ul><p>Este módulo es la base conceptual y práctica sobre la que se construirán los siguientes: Incident Response, Threat Hunting e Ingeniería de detecciones.</p><hr><h2 id="_2-objetivos-de-aprendizaje" tabindex="-1">2. Objetivos de aprendizaje</h2><p>Al completar este módulo, el estudiante debería ser capaz de:</p><ol><li>Explicar con sus propias palabras qué es un SOC, qué es un Blue Team y qué rol juegan dentro de la seguridad de una organización.</li><li>Identificar los tipos de logs y eventos más comunes que llegan a un SOC (sistema, red, aplicaciones, seguridad).</li><li>Describir los componentes básicos de una arquitectura de monitoreo (fuentes de logs → recolección → normalización → almacenamiento → análisis/alertas).</li><li>Reconocer el flujo típico de trabajo de un analista de SOC (recepción de alertas, triage, escalado).</li><li>Relacionar de forma básica actividades ofensivas (escaneos, intentos de login, uso de herramientas) con eventos/logs que un SOC podría ver.</li></ol><p>Más adelante, otros módulos profundizarán en la parte técnica (queries, reglas, playbooks, hunting), pero este módulo busca cimentar el <strong>lenguaje común y el contexto</strong>.</p><hr><h2 id="_3-areas-clave-del-modulo" tabindex="-1">3. Áreas clave del módulo</h2><p>Este módulo se divide en áreas temáticas breves, pensadas para dar una base sólida sin abrumar.</p><h3 id="_3-1-que-es-el-blue-team" tabindex="-1">3.1 Qué es el Blue Team</h3><ul><li>Definición de Blue Team y su relación con Red Team y Purple Team.</li><li>Diferencia entre defensa reactiva (SOC tradicional) y defensa más proactiva (Threat Hunting, ingeniería de detecciones).</li><li>Ejemplos de situaciones reales en las que interviene un Blue Team.</li></ul><h3 id="_3-2-introduccion-al-soc" tabindex="-1">3.2 Introducción al SOC</h3><ul><li>Qué es un <strong>Security Operations Center (SOC)</strong>.</li><li>Roles típicos dentro de un SOC: analista Tier 1, Tier 2, Tier 3, líder de turno.</li><li>Flujo básico de una alerta: generación → recepción → revisión → clasificación → escalado/cierre.</li></ul><h3 id="_3-3-telemetria-y-fuentes-de-informacion" tabindex="-1">3.3 Telemetría y fuentes de información</h3><ul><li>Tipos de logs: <ul><li>Sistema (Windows/Linux).</li><li>Red (firewalls, routers, proxies).</li><li>Aplicaciones (servidores web, aplicaciones internas, APIs).</li><li>Seguridad (EDR, antivirus, WAF, autenticación).</li></ul></li><li>Conceptos de normalización y correlación básica.</li></ul><h3 id="_3-4-herramientas-de-monitoreo-y-siem-vision-general" tabindex="-1">3.4 Herramientas de monitoreo y SIEM (visión general)</h3><ul><li>Visión general de SIEM (Security Information and Event Management).</li><li>Ejemplos de herramientas: Wazuh/OSSEC, ELK/Graylog, SIEM comerciales (sin entrar en detalle).</li><li>Qué ve un analista: dashboards, listados de eventos, reglas/queries.</li></ul><h3 id="_3-5-conexion-con-la-ruta-ofensiva" tabindex="-1">3.5 Conexión con la ruta ofensiva</h3><ul><li>Cómo los escaneos, ataques web o movimientos vistos en el área de Pentesting/Red Team se traducen en eventos que el SOC debería ver.</li><li>Ejemplos conceptuales: <ul><li>Escaneo de puertos → logs de firewall.</li><li>Intentos de login fallidos → logs de autenticación.</li><li>Acceso a rutas sensibles de una aplicación → logs de servidor web/WAF.</li></ul></li></ul><hr><h2 id="_4-estructura-del-modulo" tabindex="-1">4. Estructura del módulo</h2><p>La idea es mantener una estructura coherente con el resto de la plataforma:</p><ol><li><strong>README del módulo (este archivo):</strong> contexto, misión, objetivos y áreas clave.</li><li><strong>Teoría mínima guiada:</strong><ul><li>Conceptos básicos de Blue Team y SOC.</li><li>Ejemplos de logs y alertas.</li></ul></li><li><strong>Laboratorio 01 (por definir):</strong><ul><li>Lectura e interpretación de eventos básicos en un entorno guiado.</li><li>Relación entre una actividad ofensiva simple y los eventos que genera.</li></ul></li><li><strong>Portafolio:</strong><ul><li>Un entregable breve que el estudiante pueda guardar (por ejemplo, una ficha de &quot;Evento SOC&quot; o un mini informe explicando qué vio en el lab).</li></ul></li></ol><hr><h2 id="_5-entregables-del-modulo" tabindex="-1">5. Entregables del módulo</h2><p>Los entregables son sencillos pero orientados a que el estudiante empiece a construir <strong>material de portafolio</strong> desde el primer módulo de Blue Team.</p><h3 id="_5-1-entregable-teorico" tabindex="-1">5.1 Entregable teórico</h3><ul><li>Un breve documento (puede ser un archivo Markdown en <code>portafolio/</code>) donde el estudiante responda, en formato claro: <ul><li>¿Qué es un SOC y qué hace un Blue Team?</li><li>¿Qué tipos de logs ve un SOC a diario?</li><li>¿Qué diferencia hay entre recibir una alerta y hacer threat hunting?</li></ul></li></ul><h3 id="_5-2-entregable-practico-ligado-al-lab-01" tabindex="-1">5.2 Entregable práctico (ligado al Lab 01)</h3><p>Cuando se defina el <strong>Lab 01 del módulo</strong>, el entregable práctico esperado será algo como:</p><ul><li>Un pequeño resumen de 1–2 páginas donde el estudiante: <ul><li>Describa el escenario del lab (por ejemplo, &quot;SOC de una fintech recibiendo eventos&quot;).</li><li>Enumere algunos eventos/logs relevantes que haya observado (sin necesidad de un nivel técnico profundo todavía).</li><li>Explique cómo esos eventos podrían relacionarse con una actividad ofensiva simple.</li></ul></li></ul><blockquote><p>Más adelante, en módulos siguientes, estos entregables crecerán hasta convertirse en <strong>informes de incidente completos</strong>, timelines de ataque y reglas de detección documentadas.</p></blockquote><hr><h2 id="_6-relacion-con-otros-modulos-y-areaes" tabindex="-1">6. Relación con otros módulos y áreaes</h2><ul><li><p><strong>Área Pentesting / Red Team:</strong><br> Este módulo se apoya en lo que ya se ha visto a nivel ofensivo (por ejemplo, Recon y Pentest web), para mostrar el &quot;eco&quot; de esas acciones en la telemetría que vería un SOC.</p></li><li><p><strong>Módulos futuros de Blue Team:</strong></p><ul><li>Incident Response: tomará los conceptos de telemetría y SOC y los llevará a escenarios donde hay que contener y gestionar incidentes.</li><li>Threat Hunting: usará este mismo lenguaje de logs y eventos, pero de forma proactiva, buscando patrones anómalos.</li></ul></li><li><p><strong>Área Purple Team (más adelante):</strong><br> La comprensión básica de SOC y Blue Team será clave para diseñar ejercicios donde Red y Blue colaboran.</p></li></ul><hr><h2 id="_7-proximos-pasos" tabindex="-1">7. Próximos pasos</h2><p>Para completar este módulo a nivel de contenido y práctica, los siguientes pasos serán:</p><ol><li>Crear un <strong>Lab 01 — Introducción a eventos y alertas SOC</strong> donde el estudiante revise un conjunto de eventos simples y los relacione con acciones (benignas o maliciosas).</li><li>Diseñar una plantilla de <strong>ficha de evento SOC</strong> o mini informe de laboratorio para <code>portafolio/</code>, que el estudiante pueda completar tras el lab.</li><li>Conectar este módulo con uno de los escenarios ofensivos existentes (por ejemplo, actividad mínima contra NovaPay Labs) para que el estudiante vea el puente Red→Blue.</li></ol><p>Este módulo se seguirá ajustando a medida que se creen los labs y plantillas de informes, manteniendo siempre el enfoque profesional y práctico de la plataforma.</p>',48)])])}const g=a(l,[["render",s]]);export{p as __pageData,g as default};
